<article <?php post_class('post-card'); ?>><a class="card-image" href="<?php the_permalink(); ?>" aria-label="<?php echo esc_attr(get_the_title()); ?>"><?php if(has_post_thumbnail())the_post_thumbnail('gamezone-card',array('loading'=>'lazy'));else echo '<div class="image-placeholder" aria-hidden="true">🎮</div>'; ?></a><div class="card-body"><div class="card-category"><?php $cats=get_the_category();if($cats)echo esc_html($cats[0]->name);else esc_html_e('Artigo','gamezone'); ?></div><h3><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h3><p class="card-excerpt"><?php echo esc_html(get_the_excerpt()); ?></p><div class="card-meta"><time datetime="<?php echo esc_attr(get_the_date('c')); ?>"><?php echo esc_html(get_the_date()); ?></time><?php $r=get_post_meta(get_the_ID(),'_gamezone_rating',true);if($r!=='')echo '<span class="rating">★ '.esc_html(number_format_i18n((float)$r,1)).'/10</span>'; ?></div></div></article>